import { useEffect, useMemo, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import {
  AreaChart, Area, BarChart, Bar, PieChart, Pie, Cell,
  XAxis, YAxis, Tooltip, ResponsiveContainer, Legend, LineChart, Line,
} from "recharts";
import { Button } from "@/components/ui/button";
import { BarChart2, TrendingUp, Database, Clock, Shield, AlertOctagon, Download, FileText } from "lucide-react";

type ThreatItem = {
  id: string;
  severity: string;
  category: string;
  source_name: string;
  published_at: string;
  iocs: { cves?: string[]; ipv4?: string[]; sha256?: string[] } | null;
};

const SEV_COLORS: Record<string, string> = {
  critical: "hsl(0 84% 60%)",
  high: "hsl(38 92% 50%)",
  medium: "hsl(174 84% 52%)",
  low: "hsl(142 76% 45%)",
};

const CAT_PALETTE = [
  "hsl(174 84% 52%)", "hsl(280 70% 60%)", "hsl(38 92% 50%)", "hsl(0 84% 60%)",
  "hsl(200 80% 55%)", "hsl(120 60% 50%)", "hsl(30 90% 55%)", "hsl(250 70% 65%)",
  "hsl(60 80% 50%)", "hsl(340 70% 60%)",
];

type ChartTooltipPayload = {
  dataKey?: string;
  name?: string;
  color?: string;
  value?: number | string;
};

type ChartTooltipProps = {
  active?: boolean;
  payload?: ChartTooltipPayload[];
  label?: string;
};

function CustomTooltip({ active, payload, label }: ChartTooltipProps) {
  if (!active || !payload?.length) return null;
  return (
    <div className="rounded-lg border border-border/60 bg-card/95 px-3 py-2 text-xs shadow-lg backdrop-blur">
      {label && <div className="text-muted-foreground mb-1">{label}</div>}
      {payload.map((p) => (
        <div key={p.dataKey || p.name} className="flex items-center gap-2">
          <span className="h-2 w-2 rounded-full shrink-0" style={{ background: p.color || "hsl(var(--primary))" }} />
          <span className="text-foreground">{p.name || p.dataKey}: <strong>{p.value}</strong></span>
        </div>
      ))}
    </div>
  );
}

function exportAnalyticsReport(params: {
  timeRange: string;
  inRange: ThreatItem[];
  iocStats: { cves: number; ips: number; hashes: number };
  topSources: { name: string; count: number }[];
  topCategories: { category: string; count: number }[];
}) {
  const { timeRange, inRange, iocStats, topSources, topCategories } = params;
  const critical = inRange.filter(i => i.severity === "critical").length;
  const high = inRange.filter(i => i.severity === "high").length;
  const now = new Date().toLocaleString();

  const html = `<!DOCTYPE html><html><head>
<title>ThreatLens Analytics Report — ${now}</title>
<style>
  body { font-family: system-ui, sans-serif; max-width: 900px; margin: 40px auto; color: #1a1a2e; }
  h1 { color: #0f3460; border-bottom: 2px solid #e94560; padding-bottom: 8px; }
  h2 { color: #0f3460; font-size: 1rem; margin-top: 2rem; border-left: 4px solid #e94560; padding-left: 10px; }
  table { width: 100%; border-collapse: collapse; margin: 12px 0; }
  th, td { border: 1px solid #ddd; padding: 8px 12px; text-align: left; font-size: 0.85rem; }
  th { background: #0f3460; color: white; }
  tr:nth-child(even) { background: #f8f9fa; }
  .kpi-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin: 16px 0; }
  .kpi-card { border: 1px solid #ddd; border-radius: 8px; padding: 16px; text-align: center; }
  .kpi-value { font-size: 2rem; font-weight: bold; color: #e94560; }
  .kpi-label { font-size: 0.75rem; color: #666; margin-top: 4px; }
  .critical { color: #e94560; font-weight: bold; }
  .high { color: #f39c12; font-weight: bold; }
  .footer { margin-top: 2rem; font-size: 0.75rem; color: #999; border-top: 1px solid #ddd; padding-top: 12px; }
  @media print { body { margin: 20px; } }
</style></head><body>
<h1>ThreatLens — Threat Intelligence Analytics Report</h1>
<p><strong>Period:</strong> ${timeRange} &nbsp; <strong>Generated:</strong> ${now}</p>

<h2>Executive Summary</h2>
<div class="kpi-grid">
  <div class="kpi-card"><div class="kpi-value">${inRange.length.toLocaleString()}</div><div class="kpi-label">Total Intel Items</div></div>
  <div class="kpi-card"><div class="kpi-value critical">${critical.toLocaleString()}</div><div class="kpi-label">Critical Alerts</div></div>
  <div class="kpi-card"><div class="kpi-value high">${high.toLocaleString()}</div><div class="kpi-label">High Severity</div></div>
  <div class="kpi-card"><div class="kpi-value">${iocStats.cves.toLocaleString()}</div><div class="kpi-label">Unique CVEs</div></div>
  <div class="kpi-card"><div class="kpi-value">${iocStats.ips.toLocaleString()}</div><div class="kpi-label">Unique IPs</div></div>
  <div class="kpi-card"><div class="kpi-value">${iocStats.hashes.toLocaleString()}</div><div class="kpi-label">File Hashes</div></div>
</div>

<h2>Top Sources</h2>
<table>
  <tr><th>Source</th><th>Items</th><th>% of Total</th></tr>
  ${topSources.map(s => `<tr><td>${s.name}</td><td>${s.count}</td><td>${((s.count / (inRange.length || 1)) * 100).toFixed(1)}%</td></tr>`).join("")}
</table>

<h2>Top Categories</h2>
<table>
  <tr><th>Category</th><th>Items</th><th>% of Total</th></tr>
  ${topCategories.map(c => `<tr><td>${c.category}</td><td>${c.count}</td><td>${((c.count / (inRange.length || 1)) * 100).toFixed(1)}%</td></tr>`).join("")}
</table>

<div class="footer">Generated by ThreatLens CTI Platform — confidential and proprietary. Not for external distribution.</div>
</body></html>`;

  const win = window.open("", "_blank");
  if (!win) return;
  win.document.write(html);
  win.document.close();
  win.focus();
  setTimeout(() => win.print(), 500);
}

export default function Analytics() {
  const [items, setItems] = useState<ThreatItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [timeRange, setTimeRange] = useState("7d");

  useEffect(() => {
    setLoading(true);
    const since = new Date(Date.now() - ({
      "24h": 86400000, "7d": 7*86400000, "30d": 30*86400000,
      "90d": 90*86400000, "180d": 180*86400000, "365d": 365*86400000,
    }[timeRange] ?? 7*86400000)).toISOString();
    supabase
      .from("threat_items")
      .select("id,severity,category,source_name,published_at,iocs")
      .gte("published_at", since)
      .order("published_at", { ascending: false })
      .limit(2000)
      .then(({ data }) => {
        if (data) setItems(data as ThreatItem[]);
        setLoading(false);
      });
  }, [timeRange]);

  const rangeMs = useMemo(() => ({
    "24h": 86400000,
    "7d": 7 * 86400000,
    "30d": 30 * 86400000,
    "90d": 90 * 86400000,
    "180d": 180 * 86400000,
    "365d": 365 * 86400000,
  })[timeRange] || 7 * 86400000, [timeRange]);

  const inRange = useMemo(() => {
    const cutoff = Date.now() - rangeMs;
    return items.filter(i => new Date(i.published_at).getTime() > cutoff);
  }, [items, rangeMs]);

  // Daily volume trend
  const dailyTrend = useMemo(() => {
    const isHourly = timeRange === "24h";
    const isMonthly = timeRange === "180d" || timeRange === "365d";
    const points = isHourly ? 24 : isMonthly ? (timeRange === "180d" ? 6 : 12) : Number(timeRange.replace("d", ""));
    const bucketMs = isHourly ? 3600000 : isMonthly ? 30 * 86400000 : 86400000;
    const now = Date.now();
    const map = new Map<string, { total: number; critical: number; high: number; medium: number; low: number; ts: number }>();

    for (let i = points - 1; i >= 0; i--) {
      const t = now - i * bucketMs;
      const d = new Date(t);
      const key = isHourly
        ? `${String(d.getHours()).padStart(2, "0")}:00`
        : isMonthly
        ? d.toLocaleDateString("en-US", { month: "short", year: "2-digit" })
        : d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
      map.set(key, { total: 0, critical: 0, high: 0, medium: 0, low: 0, ts: t });
    }

    for (const item of inRange) {
      const d = new Date(item.published_at);
      const key = isHourly
        ? `${String(d.getHours()).padStart(2, "0")}:00`
        : isMonthly
        ? d.toLocaleDateString("en-US", { month: "short", year: "2-digit" })
        : d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
      const entry = map.get(key);
      if (!entry) continue;
      entry.total++;
      if (item.severity === "critical") entry.critical++;
      if (item.severity === "high") entry.high++;
      if (item.severity === "medium") entry.medium++;
      if (item.severity === "low") entry.low++;
    }

    return [...map.entries()]
      .map(([label, v]) => ({ label, ...v }))
      .sort((a, b) => a.ts - b.ts);
  }, [inRange, timeRange]);

  const cumulativeTrend = useMemo(() => {
    let running = 0;
    return dailyTrend.map((point) => {
      running += point.total;
      return { label: point.label, cumulative: running };
    });
  }, [dailyTrend]);

  // Severity distribution
  const severityDist = useMemo(() => {
    const counts: Record<string, number> = {};
    for (const i of inRange) counts[i.severity] = (counts[i.severity] || 0) + 1;
    return ["critical", "high", "medium", "low"]
      .filter(s => counts[s])
      .map(s => ({ name: s.toUpperCase(), value: counts[s], fill: SEV_COLORS[s] }));
  }, [inRange]);

  // Top categories
  const catDist = useMemo(() => {
    const counts: Record<string, number> = {};
    for (const i of inRange) counts[i.category] = (counts[i.category] || 0) + 1;
    return Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 12)
      .map(([name, value]) => ({ name: name.length > 18 ? name.slice(0, 16) + "…" : name, value }));
  }, [inRange]);

  // Top sources
  const sourceDist = useMemo(() => {
    const counts: Record<string, number> = {};
    for (const i of inRange) counts[i.source_name] = (counts[i.source_name] || 0) + 1;
    return Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 15)
      .map(([name, value]) => ({ name: name.length > 22 ? name.slice(0, 20) + "…" : name, value }));
  }, [inRange]);

  // IOC stats
  const iocStats = useMemo(() => {
    const cves = new Set<string>();
    const ips = new Set<string>();
    const hashes = new Set<string>();
    let itemsWithCve = 0, itemsWithIp = 0, itemsWithHash = 0;
    for (const i of inRange) {
      if (i.iocs?.cves?.length) { itemsWithCve++; i.iocs.cves.forEach(c => cves.add(c)); }
      if (i.iocs?.ipv4?.length) { itemsWithIp++; i.iocs.ipv4.forEach(ip => ips.add(ip)); }
      if (i.iocs?.sha256?.length) { itemsWithHash++; i.iocs.sha256.forEach(h => hashes.add(h)); }
    }
    return { cves: cves.size, ips: ips.size, hashes: hashes.size, itemsWithCve, itemsWithIp, itemsWithHash };
  }, [inRange]);

  // Top CVEs
  const topCVEs = useMemo(() => {
    const counts = new Map<string, number>();
    for (const i of inRange) for (const c of i.iocs?.cves || []) counts.set(c, (counts.get(c) || 0) + 1);
    return [...counts.entries()].sort((a, b) => b[1] - a[1]).slice(0, 10).map(([name, value]) => ({ name, value }));
  }, [inRange]);

  // Severity over time (stacked for multi-line)
  const severityTrend = useMemo(() => {
    return dailyTrend.map(d => ({ label: d.label, Critical: d.critical, High: d.high, Medium: d.medium }));
  }, [dailyTrend]);

  // Hourly heatmap — items per hour of day
  const hourlyPattern = useMemo(() => {
    const hours = Array.from({ length: 24 }, (_, h) => ({ hour: `${String(h).padStart(2, "0")}:00`, count: 0 }));
    for (const i of inRange) {
      const h = new Date(i.published_at).getHours();
      hours[h].count++;
    }
    return hours;
  }, [inRange]);

  if (loading) return (
    <div className="container mx-auto px-4 py-8 max-w-screen-xl">
      <div className="text-center py-32 text-muted-foreground">Loading analytics…</div>
    </div>
  );

  return (
    <div className="container mx-auto px-4 py-8 max-w-screen-xl">
      {/* Header */}
      <div className="mb-6 flex items-center justify-between flex-wrap gap-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight flex items-center gap-3">
            <BarChart2 className="h-8 w-8 text-primary" />
            Threat Analytics
          </h1>
          <p className="text-muted-foreground mt-1">
            Deep-dive statistics on threat intelligence data.
            {items.length === 2000 && <span className="ml-1 text-amber-400 text-xs">(showing most recent 2,000 items)</span>}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Select value={timeRange} onValueChange={setTimeRange}>
            <SelectTrigger className="w-36">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="24h">Last 24 Hours</SelectItem>
              <SelectItem value="7d">Last 7 Days</SelectItem>
              <SelectItem value="30d">Last 30 Days</SelectItem>
              <SelectItem value="90d">Last 90 Days</SelectItem>
              <SelectItem value="180d">Last 6 Months</SelectItem>
              <SelectItem value="365d">Last 1 Year</SelectItem>
            </SelectContent>
          </Select>
          <Button variant="outline" size="sm" className="gap-1.5"
            onClick={() => exportAnalyticsReport({
              timeRange,
              inRange,
              iocStats,
              topSources: sourceDist.map(s => ({ name: s.name, count: s.value })),
              topCategories: catDist.map(c => ({ category: c.name, count: c.value })),
            })}>
            <Download className="h-4 w-4" /> Export Report
          </Button>
        </div>
      </div>

      {/* KPI Row */}
      <div className="mb-6 grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-6">
        {[
          { label: "Total Items", value: inRange.length.toLocaleString(), icon: Database, color: "text-primary" },
          { label: "Critical", value: inRange.filter(i => i.severity === "critical").length.toLocaleString(), icon: AlertOctagon, color: "text-destructive" },
          { label: "High", value: inRange.filter(i => i.severity === "high").length.toLocaleString(), icon: Shield, color: "text-warning" },
          { label: "Unique CVEs", value: iocStats.cves.toLocaleString(), icon: Shield, color: "text-primary" },
          { label: "Unique IPs", value: iocStats.ips.toLocaleString(), icon: TrendingUp, color: "text-accent" },
          { label: "SHA256 Hashes", value: iocStats.hashes.toLocaleString(), icon: Clock, color: "text-muted-foreground" },
        ].map(s => (
          <Card key={s.label} className="border-border/60 bg-card/60">
            <CardContent className="p-3">
              <s.icon className={`h-4 w-4 ${s.color} mb-2`} />
              <div className={`text-xl font-bold ${s.color}`}>{s.value}</div>
              <div className="text-[10px] text-muted-foreground mt-0.5">{s.label}</div>
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Volume Trend */}
      <Card className="mb-6 border-border/60 bg-card/60 backdrop-blur">
        <CardHeader className="pb-2">
          <CardTitle className="text-sm flex items-center gap-2">
            <TrendingUp className="h-4 w-4 text-primary" />
            Threat Volume — {
              timeRange === "24h"
                ? "Last 24 Hours (hourly)"
                : timeRange === "180d" || timeRange === "365d"
                ? "Monthly aggregation"
                : `Last ${timeRange} (daily)`
            }
          </CardTitle>
        </CardHeader>
        <CardContent>
          <ResponsiveContainer width="100%" height={220}>
            <AreaChart data={dailyTrend} margin={{ top: 4, right: 4, left: -20, bottom: 0 }}>
              <defs>
                <linearGradient id="gTotal" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="hsl(174 84% 52%)" stopOpacity={0.3} />
                  <stop offset="95%" stopColor="hsl(174 84% 52%)" stopOpacity={0} />
                </linearGradient>
                <linearGradient id="gCrit" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="hsl(0 84% 60%)" stopOpacity={0.4} />
                  <stop offset="95%" stopColor="hsl(0 84% 60%)" stopOpacity={0} />
                </linearGradient>
                <linearGradient id="gHigh" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="hsl(38 92% 50%)" stopOpacity={0.3} />
                  <stop offset="95%" stopColor="hsl(38 92% 50%)" stopOpacity={0} />
                </linearGradient>
              </defs>
              <XAxis dataKey="label" tick={{ fontSize: 9, fill: "hsl(215 20% 65%)" }} interval={timeRange === "7d" ? 0 : "preserveStartEnd"} />
              <YAxis tick={{ fontSize: 9, fill: "hsl(215 20% 65%)" }} />
              <Tooltip content={<CustomTooltip />} />
              <Legend iconType="circle" iconSize={8} wrapperStyle={{ fontSize: "11px" }} />
              <Area type="monotone" dataKey="total" stroke="hsl(174 84% 52%)" fill="url(#gTotal)" strokeWidth={2} name="Total" />
              <Area type="monotone" dataKey="critical" stroke="hsl(0 84% 60%)" fill="url(#gCrit)" strokeWidth={1.5} name="Critical" />
              <Area type="monotone" dataKey="high" stroke="hsl(38 92% 50%)" fill="url(#gHigh)" strokeWidth={1.5} name="High" />
            </AreaChart>
          </ResponsiveContainer>
        </CardContent>
      </Card>

      {/* Cumulative Trend */}
      <Card className="mb-6 border-border/60 bg-card/60 backdrop-blur">
        <CardHeader className="pb-2">
          <CardTitle className="text-sm flex items-center gap-2">
            <TrendingUp className="h-4 w-4 text-accent" />
            Cumulative Threat Volume
          </CardTitle>
        </CardHeader>
        <CardContent>
          <ResponsiveContainer width="100%" height={180}>
            <LineChart data={cumulativeTrend} margin={{ top: 4, right: 4, left: -20, bottom: 0 }}>
              <XAxis dataKey="label" tick={{ fontSize: 9, fill: "hsl(215 20% 65%)" }} interval="preserveStartEnd" />
              <YAxis tick={{ fontSize: 9, fill: "hsl(215 20% 65%)" }} />
              <Tooltip content={<CustomTooltip />} />
              <Line type="monotone" dataKey="cumulative" stroke="hsl(280 70% 60%)" strokeWidth={2} dot={false} name="Cumulative" />
            </LineChart>
          </ResponsiveContainer>
        </CardContent>
      </Card>

      {/* Severity Breakdown + Category Bar */}
      <div className="mb-6 grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        {/* Severity Pie */}
        <Card className="border-border/60 bg-card/60">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm">Severity Distribution</CardTitle>
          </CardHeader>
          <CardContent>
            <ResponsiveContainer width="100%" height={220}>
              <PieChart>
                <Pie data={severityDist} cx="50%" cy="50%" innerRadius={55} outerRadius={85} paddingAngle={3} dataKey="value">
                  {severityDist.map((entry, i) => (
                    <Cell key={i} fill={entry.fill} />
                  ))}
                </Pie>
                <Tooltip content={<CustomTooltip />} />
                <Legend iconType="circle" iconSize={8} wrapperStyle={{ fontSize: "11px" }} />
              </PieChart>
            </ResponsiveContainer>
            <div className="mt-2 grid grid-cols-2 gap-2">
              {severityDist.map(s => (
                <div key={s.name} className="flex items-center justify-between text-xs border border-border/30 rounded p-2">
                  <span className="font-mono" style={{ color: s.fill }}>{s.name}</span>
                  <span className="text-muted-foreground">{s.value}</span>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        {/* Top Categories */}
        <Card className="border-border/60 bg-card/60 lg:col-span-2">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm">Top Threat Categories</CardTitle>
          </CardHeader>
          <CardContent>
            <ResponsiveContainer width="100%" height={220}>
              <BarChart data={catDist} layout="vertical" margin={{ left: 4, right: 16 }}>
                <XAxis type="number" hide />
                <YAxis type="category" dataKey="name" width={130} tick={{ fontSize: 10, fill: "hsl(215 20% 65%)" }} />
                <Tooltip content={<CustomTooltip />} />
                <Bar dataKey="value" name="Items" radius={[0, 4, 4, 0]}>
                  {catDist.map((_, i) => (
                    <Cell key={i} fill={CAT_PALETTE[i % CAT_PALETTE.length]} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </CardContent>
        </Card>
      </div>

      {/* Severity Trend Lines + Hourly Heatmap */}
      <div className="mb-6 grid gap-4 md:grid-cols-2">
        <Card className="border-border/60 bg-card/60">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm">Severity Trend by Day</CardTitle>
          </CardHeader>
          <CardContent>
            <ResponsiveContainer width="100%" height={200}>
              <LineChart data={severityTrend} margin={{ top: 4, right: 4, left: -20, bottom: 0 }}>
                <XAxis dataKey="label" tick={{ fontSize: 9, fill: "hsl(215 20% 65%)" }} interval="preserveStartEnd" />
                <YAxis tick={{ fontSize: 9, fill: "hsl(215 20% 65%)" }} />
                <Tooltip content={<CustomTooltip />} />
                <Legend iconType="circle" iconSize={8} wrapperStyle={{ fontSize: "11px" }} />
                <Line type="monotone" dataKey="Critical" stroke="hsl(0 84% 60%)" strokeWidth={2} dot={false} />
                <Line type="monotone" dataKey="High" stroke="hsl(38 92% 50%)" strokeWidth={1.5} dot={false} />
                <Line type="monotone" dataKey="Medium" stroke="hsl(174 84% 52%)" strokeWidth={1.5} dot={false} />
              </LineChart>
            </ResponsiveContainer>
          </CardContent>
        </Card>

        {/* Hourly Activity Pattern */}
        <Card className="border-border/60 bg-card/60">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm">Threat Activity by Hour of Day</CardTitle>
          </CardHeader>
          <CardContent>
            <ResponsiveContainer width="100%" height={200}>
              <BarChart data={hourlyPattern} margin={{ top: 4, right: 4, left: -20, bottom: 0 }}>
                <XAxis dataKey="hour" tick={{ fontSize: 8, fill: "hsl(215 20% 65%)" }} interval={3} />
                <YAxis tick={{ fontSize: 9, fill: "hsl(215 20% 65%)" }} />
                <Tooltip content={<CustomTooltip />} />
                <Bar dataKey="count" name="Items" fill="hsl(174 84% 52%)" opacity={0.8} radius={[2, 2, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </CardContent>
        </Card>
      </div>

      {/* Top Sources + Top CVEs */}
      <div className="mb-6 grid gap-4 md:grid-cols-2">
        <Card className="border-border/60 bg-card/60">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm">Top Sources by Volume</CardTitle>
          </CardHeader>
          <CardContent>
            <ResponsiveContainer width="100%" height={280}>
              <BarChart data={sourceDist} layout="vertical" margin={{ left: 4, right: 16 }}>
                <XAxis type="number" hide />
                <YAxis type="category" dataKey="name" width={150} tick={{ fontSize: 9, fill: "hsl(215 20% 65%)" }} />
                <Tooltip content={<CustomTooltip />} />
                <Bar dataKey="value" name="Items" fill="hsl(280 70% 60%)" radius={[0, 3, 3, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </CardContent>
        </Card>

        {/* Top CVEs */}
        <Card className="border-border/60 bg-card/60">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm">Most Referenced CVEs</CardTitle>
          </CardHeader>
          <CardContent>
            {topCVEs.length === 0 ? (
              <div className="text-center py-8 text-sm text-muted-foreground">No CVEs in this time range.</div>
            ) : (
              <>
                <ResponsiveContainer width="100%" height={180}>
                  <BarChart data={topCVEs} layout="vertical" margin={{ left: 4, right: 16 }}>
                    <XAxis type="number" hide />
                    <YAxis type="category" dataKey="name" width={140} tick={{ fontSize: 9, fill: "hsl(215 20% 65%)", fontFamily: "monospace" }} />
                    <Tooltip content={<CustomTooltip />} />
                    <Bar dataKey="value" name="References" fill="hsl(0 84% 60%)" opacity={0.8} radius={[0, 3, 3, 0]} />
                  </BarChart>
                </ResponsiveContainer>
                <div className="mt-3 space-y-1">
                  {topCVEs.slice(0, 5).map(cve => (
                    <div key={cve.name} className="flex items-center justify-between text-xs">
                      <a href={`https://nvd.nist.gov/vuln/detail/${cve.name}`} target="_blank" rel="noopener noreferrer"
                        className="font-mono text-primary hover:underline">{cve.name}</a>
                      <div className="flex items-center gap-2">
                        <span className="text-muted-foreground">{cve.value} refs</span>
                        <Badge variant="outline" className="text-[9px]">
                          <a href={`https://www.cvedetails.com/cve/${cve.name}/`} target="_blank" rel="noopener noreferrer">Details</a>
                        </Badge>
                      </div>
                    </div>
                  ))}
                </div>
              </>
            )}
          </CardContent>
        </Card>
      </div>

      {/* IOC Summary */}
      <Card className="border-border/60 bg-card/60">
        <CardHeader className="pb-2">
          <CardTitle className="text-sm">IOC Coverage ({timeRange})</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-2 gap-4 sm:grid-cols-3 lg:grid-cols-6">
            {[
              { label: "Unique CVEs", value: iocStats.cves, sub: `in ${iocStats.itemsWithCve} items`, color: "text-destructive" },
              { label: "Unique IPs", value: iocStats.ips, sub: `in ${iocStats.itemsWithIp} items`, color: "text-warning" },
              { label: "SHA256 Hashes", value: iocStats.hashes, sub: `in ${iocStats.itemsWithHash} items`, color: "text-primary" },
              { label: "IOC Coverage", value: `${Math.round(((iocStats.itemsWithCve + iocStats.itemsWithIp + iocStats.itemsWithHash) / Math.max(inRange.length, 1)) * 100)}%`, sub: "items with IOCs", color: "text-success" },
              { label: "CVE Rate", value: `${(iocStats.cves / Math.max(inRange.length, 1)).toFixed(1)}`, sub: "avg CVEs/item", color: "text-primary" },
              { label: "Total IOCs", value: iocStats.cves + iocStats.ips + iocStats.hashes, sub: "unique indicators", color: "text-foreground" },
            ].map(s => (
              <div key={s.label} className="text-center border border-border/30 rounded-lg p-3">
                <div className={`text-xl font-bold ${s.color}`}>{s.value}</div>
                <div className="text-xs font-medium text-muted-foreground mt-1">{s.label}</div>
                <div className="text-[10px] text-muted-foreground/60">{s.sub}</div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}
